:root {
  --ink: #20362b;
  --muted: #6d7d73;
  --paper: #ffffff;
  --moss: #2f6b4f;
  --mint: #e5f3e9;
  --line: #cfe1d4;
  --sun: #f2b84b;
}

.slot-card {
  width: 480px;
  box-sizing: border-box;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header,
.card-footer,
.pickup {
  display: flex;
  align-items: center;
}

.card-header {
  justify-content: space-between;
}

.eyebrow,
.detail-label,
.note {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1 {
  margin: 4px 0 0;
  font-size: 21px;
  line-height: 1.1;
}

.status {
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--moss);
  font-size: 12px;
  font-weight: 700;
}

.pickup {
  gap: 10px;
  margin: 14px 0 10px;
  padding: 10px;
  border-radius: 12px;
  background: var(--mint);
}

.calendar {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border-radius: 9px;
  background: var(--sun);
  font-size: 16px;
}

.time {
  margin: 2px 0 0;
  font-size: 15px;
  font-weight: 700;
}

.details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}

.detail {
  padding: 10px 12px;
}

.detail + .detail {
  border-left: 1px solid var(--line);
}

.detail-value {
  display: block;
  margin-top: 4px;
  font-size: 14px;
}

.card-footer {
  justify-content: space-between;
  margin-top: 12px;
}

.note {
  letter-spacing: 0;
  text-transform: none;
}

.confirm {
  padding: 8px 12px;
  border: 0;
  border-radius: 9px;
  background: var(--moss);
  color: var(--paper);
  font-size: 13px;
  font-weight: 700;
}
